def run(value_list):
    total_current_tax_expense_2017 = 0
    total_current_tax_expense_2018 = 0
    total_current_tax_expense_2019 = 0

    for value in value_list:
        if value['category'] == 'Total current tax expense' and value['header3'] in ['2017', '2018', '2019']:
            if value['header3'] == '2017':
                total_current_tax_expense_2017 += value['number_value']
            elif value['header3'] == '2018':
                total_current_tax_expense_2018 += value['number_value']
            else:
                total_current_tax_expense_2019 += value['number_value']

    total_current_tax_expense_2017 /= 1
    total_current_tax_expense_2018 /= 1
    total_current_tax_expense_2019 /= 1

    average_total_current_tax_expense = (total_current_tax_expense_2017 + total_current_tax_expense_2018 + total_current_tax_expense_2019) / 3

    if average_total_current_tax_expense < 0:
        return (round(average_total_current_tax_expense, 2), 'million')
    elif average_total_current_tax_expense < 1:
        return (round(average_total_current_tax_expense * 1000, 2), 'thousand')
    elif average_total_current_tax_expense < 1000:
        return (round(average_total_current_tax_expense * 1000000, 2), 'million')
    elif average_total_current_tax_expense < 1000000:
        return (round(average_total_current_tax_expense * 1000000000, 2), 'billion')
    else:
        return (round(average_total_current_tax_expense / 1000000000, 2), 'percent')

def run(value_list):
    total_current_tax_expense_2018 = 0
    total_current_tax_expense_2019 = 0
    total_current_tax_expense = 0

    for value in value_list:
        if value['category'] == 'Current year' and value['header3'] in ['2018', '2019']:
            if value['header3'] == '2018':
                total_current_tax_expense_2018 += value['number_value']
            else:
                total_current_tax_expense_2019 += value['number_value']
        elif value['category'] == 'Total current tax expense' and value['header3'] in ['2018', '2019']:
            total_current_tax_expense += value['number_value']

    if total_current_tax_expense_2018 + total_current_tax_expense_2019 == 0:
        return (0, '')
    elif total_current_tax_expense == 0:
        return (total_current_tax_expense_2018 + total_current_tax_expense_2019, '')
    else:
        average_total_current_tax_expense = (total_current_tax_expense_2018 + total_current_tax_expense_2019) / 2
        scale = 'million' if total_current_tax_expense_2018 + total_current_tax_expense_2019 >= 1000 else 'thousand' if total_current_tax_expense_2018 + total_current_tax_expense_2019 >= 100 else ''
        return (round(average_total_current_tax_expense, 2), scale)

def run(value_list):
    total_current_tax_expense_2017 = 0
    total_current_tax_expense_2018 = 0
    total_current_tax_expense_2019 = 0

    for item in value_list:
        if item['category'] == 'Total current tax expense' and item['header3'] == '2017':
            total_current_tax_expense_2017 += item['number_value']
        elif item['category'] == 'Total current tax expense' and item['header3'] == '2018':
            total_current_tax_expense_2018 += item['number_value']
        elif item['category'] == 'Total current tax expense' and item['header3'] == '2019':
            total_current_tax_expense_2019 += item['number_value']

    average_2017_2018 = (total_current_tax_expense_2017 - total_current_tax_expense_2018) / 1
    average_2018_2019 = (total_current_tax_expense_2018 - total_current_tax_expense_2019) / 1

    change = round((average_2018_2019 - average_2017_2018) / 1, 2)

    if abs(change) < 0.01:
        scale = ''
    elif abs(change) < 1:
        scale = 'thousand'
    elif abs(change) < 1000:
        scale = 'million'
    elif abs(change) < 1000000:
        scale = 'billion'
    else:
        scale = 'percent'

    return (change, scale)

