                total_other_comprehensive_income_2018 += item['number_value']

    change_in_total_interest_expense = (total_interest_expense_2018 - total_interest_expense_2017) / 1e6
    change_in_other_comprehensive_income = (total_other_comprehensive_income_2018 - total_other_comprehensive_income_2017) / 1e6

    if change_in_total_interest_expense > 0:
        return (round(change_in_total_interest_expense, 2), 'million')
    elif change_in_total_interest_expense < 0:
        return (round(change_in_total_interest_expense, 2), 'million')
    elif change_in_other_comprehensive_income > 0:
        return (round(change_in_other_comprehensive_income, 2), 'million')
    elif change_in_other_comprehensive_income < 0:
        return (round(change_in_other_comprehensive_income, 2), 'million')
