def run(value_list):
    legal_reserves = [item['number_value'] for item in value_list if item['category'] == 'Legal reserve']
    appropriation_earnings = [item['number_value'] for item in value_list if item['category'] == 'Appropriation of earnings (in thousand NT dollars) Appropriation of earnings (in thousand NT dollars)']
    average_legal_reserve = sum(legal_reserves) / len(legal_reserves)
    average_appropriation_earnings = sum(appropriation_earnings) / len(appropriation_earnings)

    if average_legal_reserve == average_appropriation_earnings:
        return (round(average_legal_reserve, 2), '')
    elif average_legal_reserve > average_appropriation_earnings:
        return (round(average_legal_reserve / average_appropriation_earnings, 2), 'times')
