def run(value_list):
    sep = ['thousand', 'million', 'billion', '%']
    def format_scale(scale):
        if scale in sep:
            return scale
        elif scale == '':
            return ''
        else:
            return f"{scale} {scale.capitalize()}"

    high_price = None
    low_price = None
    for item in value_list:
        if item['header2'] == 'September 29,' and item['category'] == 'High':
            high_price = item['number_value']
        elif item['header2'] == 'September 29,' and item['category'] == 'Low':
            low_price = item['number_value']

    if high_price is None or low_price is None:
        return None, None

    difference = high_price - low_price
    scale = format_scale(difference)
    return round(difference, 2), scale

