def run(value_list):
    # Filter the list for interim dividend values
    interim_dividend_values = [item for item in value_list if item['category']]

    # Extract the interim dividend values for 2018 and 2019
    interim_dividend_2018 = interim_dividend_values[0]['number_value']
    interim_dividend_2019 = interim_dividend_values[1]['number_value']

    # Calculate the percentage change
    percentage_change = ((interim_dividend_2019 - interim_dividend_2018) / interim_dividend_2018) * 100

    # Round the result to two decimal places
    percentage_change = round(percentage_change, 2)

    # Determine the scale
    if abs(percentage_change) < 1:
        scale = 'percent'
    elif abs(percentage_change) < 100:
        scale = 'thousand'
    elif abs(percentage_change) < 1000:
        scale = 'million'
    elif abs(percentage_change) < 10000:
        scale = 'billion'
    else:
        scale = ''

    # Return the result as a tuple
    return (percentage_change, scale)

